create table branches (deleted boolean default false not null, stopped boolean default false not null, code varchar(8) not null, id bigint generated by default as identity, name varchar(60) not null, primary key (id), unique (code));
create table broadcast_branches (branch_id bigint not null, broadcast_id bigint not null, primary key (broadcast_id, branch_id));
create table broadcast_recipients (branch_id bigint not null, broadcast_id bigint not null, id bigint generated by default as identity, read_at timestamp(6) with time zone, branch varchar(100) not null, username varchar(128) not null, recipient_key varchar(160) not null, primary key (id), unique (broadcast_id, recipient_key));
create table broadcasts (all_branches boolean not null, expires_at timestamp(6) with time zone, id bigint generated by default as identity, revoked_at timestamp(6) with time zone, sent_at timestamp(6) with time zone not null, priority varchar(16) not null, request_key varchar(36) not null, title varchar(120) not null, sender varchar(128) not null, body varchar(4000) not null, audience varchar(64000) not null, primary key (id), unique (request_key));
create table cashier_accounts (deleted boolean default false not null, enabled boolean not null, branch_id bigint not null, id bigint generated by default as identity, username varchar(32) not null, password_hash varchar(100) not null, primary key (id), unique (username));
create table conversation_post_reads (id bigint generated by default as identity, post_id bigint not null, read_at timestamp(6) with time zone not null, reader_key varchar(160) not null, primary key (id), unique (post_id, reader_key));
create table conversation_posts (admin boolean not null, conversation_id bigint not null, id bigint generated by default as identity, sent_at timestamp(6) with time zone not null, kind varchar(24) not null, request_key varchar(36) not null, fingerprint varchar(64) not null, sender varchar(128) not null, sender_key varchar(160) not null, body varchar(4000) not null, primary key (id), unique (request_key));
create table conversation_reads (conversation_id bigint not null, id bigint generated by default as identity, last_post_id bigint not null, read_at timestamp(6) with time zone not null, reader_key varchar(160) not null, primary key (id), unique (conversation_id, reader_key));
create table conversations (resolved boolean not null, branch_id bigint not null, created_at timestamp(6) with time zone not null, first_admin_read_at timestamp(6) with time zone, id bigint generated by default as identity, last_post_id bigint, payment_id bigint, ticket_id bigint, updated_at timestamp(6) with time zone not null, priority varchar(16) not null, category varchar(24) not null, branch varchar(100) not null, subject varchar(120) not null, cashier varchar(128) not null, owner_key varchar(160) not null, primary key (id));
create table notice_reads (id bigint generated by default as identity, notice_id bigint not null, read_at timestamp(6) with time zone not null, reader_key varchar(160) not null, primary key (id), unique (notice_id, reader_key));
create table notices (amount numeric(19,2), branch_id bigint, broadcast_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, related_id bigint, related_post_id bigint, priority varchar(16) not null, audience varchar(24) not null, related_type varchar(24), category varchar(60) not null, branch varchar(100), cashier varchar(128), sender varchar(128) not null, event_key varchar(160) not null, target_key varchar(160), title varchar(180) not null, description varchar(4000) not null, primary key (id), unique (event_key));
create table parking_rates (per_minute numeric(12,2) not null, id bigint not null, primary key (id));
create table parking_sessions (rate_per_minute numeric(12,2), entered_at timestamp(6) with time zone not null, exited_at timestamp(6) with time zone, id bigint generated by default as identity, slot_id bigint not null, active_plate varchar(24), plate varchar(24) not null, vehicle_type varchar(24) not null, entered_by varchar(32), primary key (id), unique (active_plate));
create table parking_slots (occupied boolean not null, branch_id bigint, id bigint generated by default as identity, code varchar(16) not null, primary key (id), unique (code));
create table payments (amount numeric(12,2) not null, id bigint generated by default as identity, paid_at timestamp(6) with time zone not null, session_id bigint not null unique, method varchar(16) not null, cashier_username varchar(32), reference varchar(80), primary key (id));
create index IDXh1b8f54fuvhwfakkw3ui5vga4 on conversation_post_reads (reader_key, post_id);
create index IDXpd4gw9gb9kjkc3ffv4qq3k35y on conversation_posts (conversation_id, id);
create index IDXnu3xj1l9f296v95uj8kbkjjy8 on conversation_posts (sender_key, sent_at, id);
create index IDX51gl2cmemw5jbemp1h3t56pml on conversation_posts (admin, sent_at, id);
create index IDX814hcqo88wtbm8va7ugcurj8y on conversation_reads (reader_key, conversation_id);
create index IDXl3gngpt86soqadluiecvcs7ds on conversations (owner_key, updated_at);
create index IDXlr3mxup7ab65sx866731yy3g on conversations (branch_id, updated_at);
create index IDXjfml7u7vrv6wwhfddebbb6opk on conversations (priority, resolved);
create index IDXai2w6krvbdb62os80th4qembx on notice_reads (reader_key, notice_id);
create index IDXjfwm6265vf9w5xyy5847oxin8 on notices (audience, branch_id, id);
create index IDX73y733qh5mi9tqw8duolvw632 on notices (target_key, id);
create index IDX7df03p7k4smf46mhfu9dq3y0u on notices (related_type, related_id, related_post_id);
