alter table if exists broadcast_recipients add constraint FKms8ksht7w3cvtf6u0ncouhais foreign key (broadcast_id) references broadcasts;
alter table if exists cashier_accounts add constraint FK92gxwt0bdrtfbjyu5vmdr2eik foreign key (branch_id) references branches;
alter table if exists conversation_post_reads add constraint FK9s06diplypi5u50p69lxti4nv foreign key (post_id) references conversation_posts;
alter table if exists conversation_posts add constraint FKoqfploy7lmunf609tunn5vstm foreign key (conversation_id) references conversations;
alter table if exists conversation_reads add constraint FKmgpah60y6jfhlh7j8sxb2jq6x foreign key (conversation_id) references conversations;
alter table if exists notice_reads add constraint FKh5mvl1a0vjnfm5q43krvmjy17 foreign key (notice_id) references notices;
alter table if exists notices add constraint FKg1s58agxe28snklppgm7cneb2 foreign key (broadcast_id) references broadcasts;
alter table if exists parking_sessions add constraint FKtrqvuphyoehfmvxm538kf6qyd foreign key (slot_id) references parking_slots;
alter table if exists parking_slots add constraint FKrhxcwglj0yhkvgjcosa2qvl5r foreign key (branch_id) references branches;
alter table if exists payments add constraint FKbr8q3hxwj7q3a5ratc4y5cs1n foreign key (session_id) references parking_sessions;
